import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        double n = scanner.nextDouble();
        double minDifference = 2e9;
        double ratioValue = x / y;
        double bestNum = 0;
        double bestDen = 1;
        for (int i = 1; i <= (int) n; i++) {
            long a = (long) (ratioValue * i + 0.4999);
            double diff = Math.abs((double) a / i - ratioValue);
            if (diff < minDifference) {
                minDifference = diff;
                bestNum = a;
                bestDen = i;
            }
        }
        System.out.println((long) bestNum + "/" + (long) bestDen);
        scanner.close();
    }
}
